from pwn import *
import hashlib

def generate_md5_sequence():
    md5_hashes = [hashlib.md5(str(i).encode()).hexdigest() for i in range(1, 31)]
    return ' '.join(md5_hashes)

def generate_utf8_sequence():
    utf8_chars = ''.join(chr(i) for i in range(1, 31))
    return utf8_chars

def generate_cumulative_sum_sequence():
    cumulative_sums = []
    current_sum = 0
    for i in range(1, 31):
        current_sum += i
        cumulative_sums.append(str(current_sum))
    return ' '.join(cumulative_sums)

def generate_sequence_newlines():
    return '\n'.join(str(i) for i in range(1, 31))

def connect_and_submit(payload):
    conn = remote('mandf.csaw.io', 3000)
    conn.recvline()  # Assuming there is an initial message.
    conn.sendline(payload)
    response = conn.recvall()  # Collect all remaining output.
    conn.close()
    return response

def main():
    results = {}

    # Test 1: Send MD5 hashes sequence
    md5_payload = generate_md5_sequence()
    results['MD5 Sequence'] = connect_and_submit(md5_payload)

    # Test 2: Send UTF-8 encoded characters
    utf8_payload = generate_utf8_sequence()
    results['UTF-8 Sequence'] = connect_and_submit(utf8_payload)

    # Test 3: Send cumulative sum sequence
    sum_payload = generate_cumulative_sum_sequence()
    results['Cumulative Sums'] = connect_and_submit(sum_payload)

    # Test 4: Send sequence with newlines
    newline_payload = generate_sequence_newlines()
    results['Newline Sequence'] = connect_and_submit(newline_payload)

    for test, result in results.items():
        print(f"=== {test} ===")
        print(result.decode('utf-8'))

if __name__ == "__main__":
    main()

from pwn import *
import random

def send_and_receive(data):
    with remote('mandf.csaw.io', 3000) as conn:
        conn.send(data.encode())
        response = conn.recvall().decode()
    return response

def ascending_sequence():
    data = "\n".join(str(i) for i in range(1, 31)) + "\n"
    return send_and_receive(data)

def random_numbers():
    data = "\n".join(str(random.randint(-100, 100)) for _ in range(30)) + "\n"
    return send_and_receive(data)

def identical_values():
    data = "\n".join("1" for _ in range(30)) + "\n"
    return send_and_receive(data)

def exponential_sequence():
    data = "\n".join(str(2 ** i) for i in range(30)) + "\n"
    return send_and_receive(data)

if __name__ == "__main__":
    print("Testing ascending sequence...")
    asc_result = ascending_sequence()
    print("Result for ascending sequence:\n", asc_result)

    print("Testing random numbers...")
    rand_result = random_numbers()
    print("Result for random numbers:\n", rand_result)

    print("Testing identical values...")
    ident_result = identical_values()
    print("Result for identical values:\n", ident_result)

    print("Testing exponential sequence...")
    exp_result = exponential_sequence()
    print("Result for exponential sequence:\n", exp_result)

from pwn import *

def connect_and_test():
    # Connect to the challenge server
    conn = remote('mandf.csaw.io', 3000)

    # Test cases
    tests = {
        "high_variance": "-1000\n1000\n" * 15,
        "specific_mean": "48\n49\n50\n" * 10,
        "distinct_clusters": "1\n" * 15 + "100\n" * 15,
        "symmetry": "-15\n-10\n-5\n0\n5\n10\n15\n" * 2
    }

    responses = {}

    for test_name, test_input in tests.items():
        conn.send(test_input + "\n")  # Send test input
        response = conn.recvline().strip().decode()  # Receive the response
        responses[test_name] = response  # Record response

    conn.close()
    return responses

if __name__ == "__main__":
    responses = connect_and_test()
    for test_name, response in responses.items():
        print(f"Test: {test_name}\nResponse: {response}\n")
